    private $database;
    public function __construct($database){$this->database=$database;}
    public function updateOpenFindings($status,$ids){$status=$status==='ignored'?'ignored':'resolved';$ids=is_array($ids)?$ids:array();$ids=array_values(array_unique(array_filter(array_map('intval',$ids),static function($id){return $id>0;})));if(!$ids)return 0;$list=implode(',',array_slice($ids,0,1000));$result=$this->database->query("SELECT COUNT(*) AS total FROM `{TP}mod_security_center_findings` WHERE status='open' AND id IN ($list)");$row=$result?$result->fetchRow(MYSQLI_ASSOC):null;$count=(int)($row['total']??0);if($count>0)$this->database->query("UPDATE `{TP}mod_security_center_findings` SET status='$status' WHERE status='open' AND id IN ($list)");return $count;}
    public function updateOpenFindingsByFilter($status,$filter)
    {
        $status=$status==='ignored'?'ignored':'resolved';
        $filter=is_array($filter)?$filter:array();
        $where="status='open'";
        $severity=(string)($filter['severity']??'');
        if(in_array($severity,array('low','medium','high','critical'),true))$where.=" AND severity='".$this->database->escapeString($severity)."'";
        $rule=trim((string)($filter['rule']??''));
        if($rule!=='')$where.=" AND rule_id='".$this->database->escapeString($rule)."'";
        $search=trim((string)($filter['search']??''));
        if($search!==''){
            $like="%".$this->database->escapeString(substr($search,0,250))."%";
            $where.=" AND (file_path LIKE '".$like."' OR message LIKE '".$like."' OR rule_id LIKE '".$like."')";
        }
        $result=$this->database->query("SELECT COUNT(*) AS total FROM `{TP}mod_security_center_findings` WHERE $where");
        $row=$result?$result->fetchRow(MYSQLI_ASSOC):null;
        $count=(int)($row['total']??0);
        if($count>0)$this->database->query("UPDATE `{TP}mod_security_center_findings` SET status='$status' WHERE $where");
        return $count;
    }

    private function tableExists($name)
    {
        if(!defined('TABLE_PREFIX'))return false;
        try{$result=$this->database->query("SHOW TABLES LIKE '".$this->database->escapeString(TABLE_PREFIX.$name)."'");return $result&&$result->fetchRow()?true:false;}catch(Throwable $exception){return false;}
    }
