    private function syncWorkerIntervals(){ $settings=$this->settings();$items=array('security_center.code_scan'=>(int)$settings['scanner_interval_minutes'],'security_center.integrity'=>(int)$settings['integrity_interval_minutes'],'security_center.notifications'=>(int)$settings['notification_digest_minutes']);foreach($items as $worker=>$minutes){$cron=self::intervalCron($minutes);$this->database->query("UPDATE `{TP}mod_worker_tasks` SET cron_expression='".$this->database->escapeString($cron)."',modified_at='".gmdate('Y-m-d H:i:s')."' WHERE worker_id='".$this->database->escapeString($worker)."' AND managed=1");}}
    private static function intervalCron($minutes){$minutes=max(1,min(1440,(int)$minutes));if($minutes<60)return '*/'.$minutes.' * * * *';if($minutes>=1440)return '0 0 * * *';$hours=max(1,min(23,(int)round($minutes/60)));return '0 */'.$hours.' * * *';}
    public function toggleSetting($name,$enabled){$allowed=array('firewall_enabled','sqli_protection','xss_protection','path_protection','bad_bot_protection','bot_builtin_signatures','bot_custom_signatures','bot_custom_case_sensitive','fake_bot_protection','fake_bot_google','fake_bot_bing','spam_protection','proxy_protection','bad_words_filter','bad_words_case_sensitive','missing_user_agent_block','security_headers','block_php_uploads','auto_ban_enabled','scanner_enabled','virus_scanner_enabled','integrity_enabled','traffic_logging','email_notifications');if(!in_array($name,$allowed,true))throw new InvalidArgumentException('Diese Schutzfunktion kann nicht direkt geschaltet werden.');self::put($this->database,$name,$enabled?'1':'0');self::writeRuntime($this->database);}
    public static function isExtendedToggle($name)
    {
        return in_array((string)$name,array('request_check_get','request_check_post','request_check_cookies','request_check_body','request_check_path','xss_script_tags','xss_event_handlers','xss_dangerous_urls','xss_active_tags','sqli_union_select','sqli_time_functions','sqli_boolean_conditions','sqli_stacked_queries','path_stream_wrappers','path_traversal_sequences','upload_check_extension','upload_check_content'),true);
    }
    public function toggleExtendedSetting($name,$enabled)
    {
        if(!self::isExtendedToggle($name))throw new InvalidArgumentException('Diese Detailfunktion kann nicht direkt geschaltet werden.');
        self::put($this->database,$name,$enabled?'1':'0');self::writeRuntime($this->database);
    }
    public function saveExtendedProtectionSettings($input)
    {
        if(($input['setting_scope']??'')!=='protection')return;
        foreach(array_keys(self::extendedProtectionDefaults()) as $name){
            if(self::isExtendedToggle($name))self::put($this->database,$name,!empty($input[$name])?'1':'0');
        }
        $selects=array('xss_action','sqli_action','path_action','upload_action','login_rate_action');
        foreach($selects as $name)if(isset($input[$name])&&in_array($input[$name],array('monitor','block'),true))self::put($this->database,$name,$input[$name]);
        if(array_key_exists('upload_scan_bytes',$input))self::put($this->database,'upload_scan_bytes',(string)max(4096,min(1048576,(int)$input['upload_scan_bytes'])));
        self::writeRuntime($this->database);
    }
    public function addRule($input){$kinds=array('allow_ip','block_ip','block_cidr','country','user_agent','browser','os','isp','referrer','bad_word','file_allow');$kind=in_array(($input['kind']??''),$kinds,true)?$input['kind']:'';$pattern=trim((string)($input['pattern']??''));if($kind===''||$pattern===''||strlen($pattern)>500)throw new InvalidArgumentException('Ungültige Regel.');if(in_array($kind,array('allow_ip','block_ip'),true)&&filter_var($pattern,FILTER_VALIDATE_IP)===false)throw new InvalidArgumentException('Bitte eine gültige IPv4- oder IPv6-Adresse eingeben.');if($kind==='block_cidr'&&!preg_match('~^[0-9a-f:.]+/(?:[0-9]|[1-9][0-9]|1[01][0-9]|12[0-8])$~i',$pattern))throw new InvalidArgumentException('Bitte einen gültigen IP-Bereich in CIDR-Notation eingeben.');if($kind==='country'){$pattern=strtoupper($pattern);if(!preg_match('/^[A-Z]{2}$/',$pattern))throw new InvalidArgumentException('Bitte einen zweistelligen Ländercode eingeben.');}if($kind==='referrer'){$pattern=strtolower($pattern);if(!preg_match('/^(?:[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z]{2,63}$/i',$pattern))throw new InvalidArgumentException('Bitte nur einen gültigen Domainnamen eingeben.');}if($kind==='file_allow'&&(str_contains($pattern,'..')||str_starts_with($pattern,'/')))throw new InvalidArgumentException('Bitte einen sicheren relativen Dateipfad eingeben.');$action=str_starts_with($kind,'allow_')||$kind==='file_allow'?'allow':($kind==='bad_word'?'filter':'block');$this->database->query("INSERT IGNORE INTO `{TP}mod_security_center_rules` (kind,pattern,action,enabled,note,created_at) VALUES ('".$this->database->escapeString($kind)."','".$this->database->escapeString($pattern)."','$action',1,'".$this->database->escapeString(substr((string)($input['note']??''),0,500))."','".gmdate('Y-m-d H:i:s')."')");self::writeRuntime($this->database);}
