        if(filter_var($address,FILTER_VALIDATE_IP)===false)throw new InvalidArgumentException('Bitte eine gültige IPv4- oder IPv6-Adresse eingeben.');
        $enabled=!empty($input['enabled'])?1:0;$note=substr(trim((string)($input['note']??'')),0,500);$expires=null;
        if(trim((string)($input['expires_at']??''))!==''){$zone=new DateTimeZone(date_default_timezone_get());if(function_exists('wbce_timezone')){$candidate=wbce_timezone();if($candidate instanceof DateTimeZone)$zone=$candidate;}elseif(defined('TIMEZONE_IDENTIFIER')){$zone=new DateTimeZone((string)TIMEZONE_IDENTIFIER);}$date=DateTimeImmutable::createFromFormat('Y-m-d\TH:i',(string)$input['expires_at'],$zone);if(!$date)throw new InvalidArgumentException('Das Ablaufdatum ist ungültig.');$expires=$date->setTimezone(new DateTimeZone('UTC'))->format('Y-m-d H:i:s');}
        $now=gmdate('Y-m-d H:i:s');$expirySql=$expires===null?'NULL':"'".$this->database->escapeString($expires)."'";
        if($id>0)$this->database->query("UPDATE `{TP}mod_security_center_bans` SET address='".$this->database->escapeString($address)."',note='".$this->database->escapeString($note)."',enabled=$enabled,expires_at=$expirySql,updated_at='$now' WHERE id=$id");
        else $this->database->query("INSERT INTO `{TP}mod_security_center_bans` (address,reason,source,note,enabled,expires_at,created_at,updated_at) VALUES ('".$this->database->escapeString($address)."','manual','manual','".$this->database->escapeString($note)."',$enabled,$expirySql,'$now','$now') ON DUPLICATE KEY UPDATE note=VALUES(note),enabled=VALUES(enabled),expires_at=VALUES(expires_at),updated_at=VALUES(updated_at)");
        self::writeRuntime($this->database);
    }
    public function changeTemporaryBan($id,$action)
