    }
    public function clearTemporaryBans(){if($this->tableExists('mod_security_center_bans'))$this->database->query('DELETE FROM `{TP}mod_security_center_bans`');self::put($this->database,'temporary_bans',array());self::writeRuntime($this->database);}
    public static function refreshRuntime($database){self::writeRuntime($database);}
    private static function writeRuntime($database)
    {
        $service=new self($database);$settings=$service->settings();$compiled=array('allow'=>array(),'block'=>array(),'bad_word'=>array(),'user_agent'=>array(),'referrer'=>array(),'country'=>array(),'isp'=>array(),'file_allow'=>array());
        $r=$database->query('SELECT kind,pattern FROM `{TP}mod_security_center_rules` WHERE enabled=1');
        while($r&&($row=$r->fetchRow(MYSQLI_ASSOC))){if($row['kind']==='allow_ip')$compiled['allow'][]=$row['pattern'];elseif(in_array($row['kind'],array('block_ip','block_cidr'),true))$compiled['block'][]=$row['pattern'];elseif($row['kind']==='bad_word')$compiled['bad_word'][]=$row['pattern'];elseif(in_array($row['kind'],array('user_agent','browser','os'),true))$compiled['user_agent'][]=$row['pattern'];elseif($row['kind']==='referrer')$compiled['referrer'][]=$row['pattern'];elseif($row['kind']==='country')$compiled['country'][]=$row['pattern'];elseif($row['kind']==='isp')$compiled['isp'][]=$row['pattern'];elseif($row['kind']==='file_allow')$compiled['file_allow'][]=$row['pattern'];}
        $settings['compiled_rules']=$compiled;$settings['bot_verifications']=array();$now=gmdate('Y-m-d H:i:s');$bots=$database->query("SELECT ip_hash,verified FROM `{TP}mod_security_center_bot_cache` WHERE expires_at>'$now'");while($bots&&($bot=$bots->fetchRow(MYSQLI_ASSOC)))$settings['bot_verifications'][$bot['ip_hash']]=(bool)$bot['verified'];
        $legacy=(array)($settings['temporary_bans']??array());$active=array();foreach($legacy as $key=>$expiry)if((int)$expiry>time())$active[$key]=(int)$expiry;
        if($service->tableExists('mod_security_center_bans')){$bans=$database->query("SELECT address,expires_at FROM `{TP}mod_security_center_bans` WHERE enabled=1 AND (expires_at IS NULL OR expires_at>'$now')");while($bans&&($ban=$bans->fetchRow(MYSQLI_ASSOC)))$active[$ban['address']]=$ban['expires_at']===null?PHP_INT_MAX:(int)strtotime($ban['expires_at'].' UTC');}
        $settings['temporary_bans']=$active;require_once __DIR__.'/RuntimeConfig.php';WbceSecurityCenterRuntimeConfig::write($settings);
    }
    public function event($type,$severity='info',$details=array()){if(!$this->tableExists('mod_security_center_events'))return;$type=preg_replace('/[^a-z0-9._-]/i','',(string)$type);if($type==='')return;$severity=in_array($severity,array('info','warning','critical'),true)?$severity:'info';$settings=$this->settings();$key=defined('DB_PASSWORD')?(string)DB_PASSWORD:__DIR__;if(!class_exists('WbceSecurityCenterFirewall',false)&&is_file(__DIR__.'/Firewall.php'))require_once __DIR__.'/Firewall.php';$address=class_exists('WbceSecurityCenterFirewall',false)?WbceSecurityCenterFirewall::clientAddress($settings):(string)($_SERVER['REMOTE_ADDR']??'cli');$ip=hash_hmac('sha256',$address,$key);$now=gmdate('Y-m-d H:i:s');$this->database->query("INSERT INTO `{TP}mod_security_center_events` (event_type,severity,ip_hash,request_path,details,created_at) VALUES ('".$this->database->escapeString($type)."','$severity','$ip','".$this->database->escapeString(substr((string)($_SERVER['REQUEST_URI']??''),0,500))."','".$this->database->escapeString((string)json_encode($details))."','$now')");if($type==='firewall.blocked'&&($settings['auto_ban_enabled']??'0')==='1')$this->updateTemporaryBan($address,$ip,$settings,(string)($details['reason']??''));$rank=array('info'=>1,'warning'=>2,'critical'=>3);$notify=$this->notificationEnabled($type,$settings);if($notify&&($settings['email_notifications']??'0')==='1'&&!empty($settings['notification_email'])&&$rank[$severity]>=$rank[$settings['notification_min_severity']??'critical']){$eventId=is_callable(array($this->database,'getLastInsertId'))?(int)$this->database->getLastInsertId():0;if($eventId&&$this->tableExists('mod_security_center_notifications'))$this->database->query("INSERT INTO `{TP}mod_security_center_notifications` (event_id,status,created_at) VALUES ($eventId,'queued','$now')");}}
    private function notificationEnabled($type,$settings){if(str_starts_with($type,'firewall.'))return ($settings['notify_firewall']??'1')==='1';if(str_starts_with($type,'auth.'))return ($settings['notify_auth']??'1')==='1';if(str_starts_with($type,'file.'))return ($settings['notify_files']??'1')==='1';if(str_starts_with($type,'addon.'))return ($settings['notify_addons']??'0')==='1';return true;}
    private function updateTemporaryBan($address,$ipHash,$settings,$reason='')
    {
        $window=max(1,(int)($settings['auto_ban_minutes']??60));$since=gmdate('Y-m-d H:i:s',time()-$window*60);$r=$this->database->query("SELECT COUNT(*) total FROM `{TP}mod_security_center_events` WHERE event_type='firewall.blocked' AND ip_hash='".$this->database->escapeString($ipHash)."' AND created_at>='$since'");$row=$r?$r->fetchRow(MYSQLI_ASSOC):null;if(!$row||(int)$row['total']<max(2,(int)($settings['auto_ban_threshold']??5)))return;
        $expiry=gmdate('Y-m-d H:i:s',time()+$window*60);$now=gmdate('Y-m-d H:i:s');
        if($this->tableExists('mod_security_center_bans')&&filter_var($address,FILTER_VALIDATE_IP))$this->database->query("INSERT INTO `{TP}mod_security_center_bans` (address,reason,source,note,enabled,expires_at,created_at,updated_at) VALUES ('".$this->database->escapeString($address)."','".$this->database->escapeString(substr((string)$reason,0,100))."','automatic','',1,'$expiry','$now','$now') ON DUPLICATE KEY UPDATE reason=VALUES(reason),source='automatic',enabled=1,expires_at=VALUES(expires_at),updated_at=VALUES(updated_at)");
        else{$bans=(array)($settings['temporary_bans']??array());$bans[$ipHash]=time()+$window*60;self::put($this->database,'temporary_bans',$bans);}
        self::writeRuntime($this->database);
    }
