    public function queueDiagnostic($input){$type=(string)($input['diagnostic_type']??'');$allowed=array('ip_lookup','fake_bot','port_scan','dnsbl');if(!in_array($type,$allowed,true))throw new InvalidArgumentException('Unbekannte Diagnose.');$target=trim((string)($input['diagnostic_target']??''));if($type==='port_scan'){$target='127.0.0.1';$raw=isset($input['diagnostic_port_values'])?(array)$input['diagnostic_port_values']:preg_split('/[\s,;]+/',(string)($input['diagnostic_ports']??'80,443'));$ports=array_values(array_unique(array_filter(array_map('intval',$raw),static fn($port)=>$port>0&&$port<=65535)));sort($ports);if(!$ports||count($ports)>20)throw new InvalidArgumentException('Bitte 1 bis 20 gültige Ports angeben.');$configuration=array('ports'=>$ports,'display_host'=>(string)(parse_url(WB_URL,PHP_URL_HOST)?:'localhost'));}else{if(filter_var($target,FILTER_VALIDATE_IP)===false)throw new InvalidArgumentException('Bitte eine gültige IP-Adresse eingeben.');$configuration=array();}$this->database->query("INSERT INTO `{TP}mod_security_center_diagnostics` (job_type,target,configuration,status,created_at) VALUES ('".$this->database->escapeString($type)."','".$this->database->escapeString($target)."','".$this->database->escapeString(json_encode($configuration))."','queued','".gmdate('Y-m-d H:i:s')."')");return method_exists($this->database,'getLastInsertId')?(int)$this->database->getLastInsertId():0;}
