    public function saveHtaccess($content){$content=(string)$content;if(strlen($content)>262144||str_contains($content,"\0")||preg_match('/<\?(?:php|=)?/i',$content))throw new InvalidArgumentException('Der Inhalt der .htaccess-Datei ist ungültig oder zu groß.');$path=WB_PATH.'/.htaccess';$backup=WB_PATH.'/.htaccess.security-center-backup';if(is_file($path)&&!@copy($path,$backup))throw new RuntimeException('Die Sicherungskopie der .htaccess-Datei konnte nicht angelegt werden.');$temporary=$path.'.security-center-'.bin2hex(random_bytes(4));if(@file_put_contents($temporary,$content,LOCK_EX)===false||!@rename($temporary,$path)){@unlink($temporary);throw new RuntimeException('Die .htaccess-Datei konnte nicht gespeichert werden.');}@chmod($path,0644);}
    public function fixPhpSetting($name,$enabled=true){if(func_num_args()<2)$enabled=!empty($_POST['setting_value']);require_once __DIR__.'/PhpRuntime.php';$secure=array('display_errors'=>'0','display_startup_errors'=>'0','log_errors'=>'1','expose_php'=>'0','allow_url_include'=>'0','session.cookie_httponly'=>'1','session.use_strict_mode'=>'1','session.use_only_cookies'=>'1','session.use_trans_sid'=>'0','phar.require_hash'=>'1','phar.readonly'=>'1');if(!isset($secure[$name])||!in_array($name,WbceSecurityCenterPhpRuntime::allowed(),true))throw new InvalidArgumentException('Diese PHP-Einstellung kann nicht verwaltet werden.');$all=ini_get_all(null,true);$access=(int)($all[$name]['access']??0);$sessionActive=function_exists('session_status')&&session_status()===PHP_SESSION_ACTIVE;if(!($access&1)||($sessionActive&&str_starts_with($name,'session.')))throw new RuntimeException('Diese Einstellung kann in der aktuellen PHP-Laufzeit nicht verändert werden.');$value=$enabled?'1':'0';$previous=(string)ini_get($name);$result=@ini_set($name,$value);if($result===false||!self::iniValueMatches((string)ini_get($name),$value)){@ini_set($name,$previous);throw new RuntimeException('PHP hat die Änderung dieser Einstellung abgelehnt.');}try{$settings=$this->settings();$runtime=$settings['php_runtime_settings']??array();if(!is_array($runtime))$runtime=array();$runtime[$name]=$value;self::put($this->database,'php_runtime_settings',$runtime);$saved=$this->settings();$savedRuntime=(array)($saved['php_runtime_settings']??array());if(!isset($savedRuntime[$name])||(string)$savedRuntime[$name]!==$value)throw new RuntimeException('Die gespeicherte PHP-Einstellung konnte nicht bestätigt werden.');self::writeRuntime($this->database);WbceSecurityCenterPhpRuntime::apply($saved);if(!self::iniValueMatches((string)ini_get($name),$value))throw new RuntimeException('Die gespeicherte PHP-Einstellung konnte nicht angewendet werden.');}catch(Throwable $exception){@ini_set($name,$previous);throw $exception;}re